	[ 'eans' => [ '0036282017849', '0036282017856', '0036282017863', '0036282017917', '0036282017924', '0036282017931', '0036282017948', '0036282017979', '0036282017986' ], 'html' => '<p>Superior fra Abu Garcia er et spinnehjul bygget som allrounder til ferskvandsfiskeri. Med nyeste teknologi og lette materialer skal det køre jævnt og holde længe.</p>' ],
