	[ 'eans' => [ '0887194498642', '0887194498635', '0887194498628', '0887194498611', '0887194498604', '0887194498598', '0887194498581', '0887194498703', '0887194498697', '0887194498680' ], 'html' => '<p>Vinterstøvler til damer fra Keen med KEEN.Warm og KEEN.Dry, vandtætte og lavet til fodfæste på isglatte forhold. Revel III i Black / Rose.</p><ul><li>KEEN.Warm</li><li>KEEN.Dry</li></ul>' ],
